public str getPriceAttributeSourceSymbol()
{
    DictClass dc;
    dc = this.PriceAttributeClassId == classNum(UPSPricingAttributeEcoResAttribute) ? new DictClass(this.AttributeProviderClassId) : new DictClass(this.PriceAttributeClassId);
    return enum2Symbol(enumNum(UPSPricingAttributeSource), (dc.getAttribute('UPSPricingAttributeSourceDiscoveryAttribute') as UPSPricingAttributeSourceDiscoveryAttribute).parmSource());

}

/// <summary>
/// Get the related pricing attribute.
/// </summary>
/// <returns>The pricing attribute.</returns>
public UPSIPricingAttribute pricingAttribute()
{
    return UPSPricingAttributeRepository::priceAttribute(
        this.PriceAttributeClassId,
        this.AttributeProviderClassId,
        this.AttributeName,
        this.TypeName);
}

public static UPSPricingAttributeLink find(RecId _recId, boolean _update = false)
{
    UPSPricingAttributeLink  pricingAttributeLink;

    pricingAttributeLink.selectForUpdate(_update);

    if (_recId)
    {
        select firstonly pricingAttributeLink
            where pricingAttributeLink.RecId == _recId;
    }

    return pricingAttributeLink;
}

public Set getAttributeGroupRecIdRecordSet()
{
    UPSPricingAttributeLink pricingAttributeLink;
    UPSPricingAttributeGroup pricingAttributeGroup;
    Set recordSet = new Set(Types::Int64);

    while select PriceAttributeGroup from pricingAttributeLink join pricingAttributeGroup
        where pricingAttributeLink.PriceAttributeGroup == pricingAttributeGroup.RecId
            && pricingAttributeGroup.IsValid == NoYes::Yes
            && pricingAttributeLink.PriceAttributeClassId == this.PriceAttributeClassId
            && pricingAttributeLink.AttributeName == this.AttributeName
            && pricingAttributeLink.TypeName == this.TypeName
    {
        recordSet.add(pricingAttributeLink.PriceAttributeGroup);
    }

    return recordSet;
}

public void moveUp()
{
    UPSPricingAttributeLink swapPricingAttributeLink;

    select forupdate firstonly DisplayOrder from swapPricingAttributeLink
        order by DisplayOrder desc
        where this.PriceAttributeGroup == swapPricingAttributeLink.PriceAttributeGroup &&
        this.DisplayOrder > swapPricingAttributeLink.DisplayOrder;

    if (swapPricingAttributeLink)
    {
        this.swapDisplayOrder(swapPricingAttributeLink);
    }
}

public void moveDown()
{
    UPSPricingAttributeLink swapPricingAttributeLink;

    select forupdate firstonly DisplayOrder from swapPricingAttributeLink
        order by DisplayOrder asc
        where this.PriceAttributeGroup == swapPricingAttributeLink.PriceAttributeGroup &&
        this.DisplayOrder < swapPricingAttributeLink.DisplayOrder;

    if (swapPricingAttributeLink)
    {
        this.swapDisplayOrder(swapPricingAttributeLink);
    }
}

    private void swapDisplayOrder(UPSPricingAttributeLink _newpricingAttributeLink)
    {
        int newDisplayOrder;

        ttsbegin;
        newDisplayOrder = _newpricingAttributeLink.DisplayOrder;
        _newpricingAttributeLink.DisplayOrder = this.DisplayOrder;
        _newpricingAttributeLink.update();
        this.DisplayOrder = newDisplayOrder;
        this.update();
        ttscommit;
	}

/// <summary>
/// Display a lookup form with all allowed values.
/// </summary>
/// <param name = "_control">The target control to be linked with the lookup form.</param>
public void lookupAllowedValues(FormStringControl _control)
{
    SysTableLookup    lookup;
    QueryBuildDataSource qbds;
    Query q = new Query();
    qbds = q.addDataSource(tableNum(UPSAllowedValuesListTemp));
    qbds.addSortField(fieldNum(UPSAllowedValuesListTemp, Value), SortOrder::Ascending);

    lookup = SysTableLookup::newParameters(tableNum(UPSAllowedValuesListTemp),
                                           _control,
                                           true);

    lookup.addLookupField(fieldnum(UPSAllowedValuesListTemp, Value), true);
    lookup.parmQuery(q);
    lookup.parmTmpBuffer(UPSAllowedValuesListTemp::populate(this.pricingAttribute().getAllowedValues()));

    lookup.performFormLookup();
}

/// <summary>
/// Convert <c>AttributeDataType</c> to EcoResValue
/// </summary>
/// <param name = "_dataType">Type of condition value</param>
/// <param name = "_value">Value to check</param>
/// <returns>EcoResValue record</returns>
internal static EcoResValue getEcoResValue(AttributeDataType _dataType, AttributeValueText _value)
{
    EcoResValue ecoResValue;

    switch (_dataType)
    {
        case AttributeDataType::Decimal:
            EcoResFloatValue ecoResFloatValue;

            ecoResFloatValue.FloatValue = str2Num(_value);
            ecoResValue                 = ecoResFloatValue;
            break;
        case AttributeDataType::Integer:
            EcoResIntValue ecoResIntValue;

            ecoResIntValue.IntValue = str2Int(_value);
            ecoResValue             = ecoResIntValue;
            break;
        case AttributeDataType::Currency:
            EcoResCurrencyValue ecoResCurrencyValue;

            ecoResCurrencyValue.CurrencyValue   = str2Num(_value);
            ecoResValue                         = ecoResCurrencyValue;
            break;
        case AttributeDataType::DateTime:
            EcoResDateTimeValue ecoResDateTimeValue;
            System.Globalization.CultureInfo culture = System.Globalization.CultureInfo::get_InvariantCulture();

            try
            {
                utcdatetime dateTime = System.DateTime::ParseExact(_value, 'g', culture);
                ecoResDateTimeValue.DateTimeValue = dateTime;
            }
            catch (Exception::CLRError)
            {
                throw error(strFmt("@UnifiedPricingService:UPSDateTimeFormatError", culture.DateTimeFormat.ShortDatePattern, culture.DateTimeFormat.ShortTimePattern));
            }

            ecoResValue = ecoResDateTimeValue;
            break;
        case AttributeDataType::Text:
            EcoResTextValue ecoResTextValue;

            ecoResTextValue.TextValue   = _value;
            ecoResValue                 = ecoResTextValue;
            break;
    }

    return ecoResValue;
}

/// <summary>
/// Validate the value
/// </summary>
/// <returns>True if the value is correct; Otherwise false</returns>
internal boolean checkDefaultValue()
{
    boolean ret = true;

    if (this.DefaultValue)
    {
        if (this.PriceAttributeClassId == classNum(UPSPricingAttributeEcoResAttribute))
        {
            EcoResAttributeDefaultValueHelper attributeDefaultValueHelper = new EcoResAttributeDefaultValueHelper(EcoResAttributeType::findByName(this.TypeName));
            AttributeDataType attributeDataType = this.pricingAttribute().getDataType();

            if (attributeDataType != AttributeDataType::TrueFalse
                && attributeDataType != AttributeDataType::Reference
                && !attributeDefaultValueHelper.validateDefaultValue(UPSPricingAttributeLink::getEcoResValue(attributeDataType, this.DefaultValue)))
            {
                ret = checkFailed(strFmt("@UnifiedPricingService:UPSAttributeValueRangeError", this.DefaultValue, this.TypeName));
            }
        }
        else
        {
            Set allowedValues = this.pricingAttribute().getAllowedValues();

            if (!allowedValues.in(this.DefaultValue))
            {
                ret = checkFailed(strFmt("@UnifiedPricingService:UPSAttributeValueIsNotAllowed", this.DefaultValue, this.AttributeName));
            }
        }
    }

    return ret;
}

/// <summary>
/// Validate write.
/// </summary>
/// <returns>True or false.</returns>
public boolean validateWrite()
{
    boolean ret = super();

    if (UPSPricingAttributeGroup::isPricingAttributeGroupUsed(this.PriceAttributeGroup))
    {
        warning("@UnifiedPricingService:UPSPricingAttributeGroupIsUsed");
        ret = false;
    }

    if (ret)
    {
        ret = ret && this.checkDefaultValue();
    }

    return ret;
}

public boolean validateDelete()
{
    boolean ret = super();

    if (UPSPricingAttributeGroup::isPricingAttributeGroupUsed(this.PriceAttributeGroup))
    {
        warning("@UnifiedPricingService:UPSPricingAttributeGroupIsUsed");
        ret = false;
    }

    return ret;
}
